package e.e.a;
import android.view.*;import android.widget.*;import java.util.*;
/** Long hold then drag reorders live cells; release without moving opens tab actions. */
final class TabDrag228 implements View.OnTouchListener,View.OnLongClickListener {
 final MultiTabs227.Host host;final View cell;final SavedTabs227.Tab tab;final HorizontalScrollView scroll;boolean armed,moved;float start;ArrayList<SavedTabs227.Tab> before;final Map<String,View> cells=new HashMap<>();
 TabDrag228(MultiTabs227.Host h,View v,SavedTabs227.Tab t,HorizontalScrollView s){host=h;cell=v;tab=t;scroll=s;}
 static void install(MultiTabs227.Host h,View v,SavedTabs227.Tab t,HorizontalScrollView s){TabDrag228 drag=new TabDrag228(h,v,t,s);v.setTag(t.id);v.setOnTouchListener(drag);v.setOnLongClickListener(drag);}
 public boolean onLongClick(View v){cells.clear();for(int i=0;i<host.strip.getChildCount();i++){View item=host.strip.getChildAt(i);cells.put(String.valueOf(item.getTag()),item);}armed=true;moved=false;before=new ArrayList<SavedTabs227.Tab>(MultiTabs227.data().tabs);v.setAlpha(.65f);v.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);v.getParent().requestDisallowInterceptTouchEvent(true);return true;}
 public boolean onTouch(View v,MotionEvent e){int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){start=e.getRawX();armed=false;moved=false;return false;}if(!armed)return false;if(action==MotionEvent.ACTION_CANCEL||e.getPointerCount()>1){MultiTabs227.data().tabs.clear();MultiTabs227.data().tabs.addAll(before);finish(false);return true;}if(action==MotionEvent.ACTION_MOVE){if(Math.abs(e.getRawX()-start)>ViewConfiguration.get(v.getContext()).getScaledTouchSlop())moved=true;if(moved){int[] origin=new int[2];host.strip.getLocationOnScreen(origin);float x=e.getRawX()-origin[0];int target=0;float slot=0;java.util.List<SavedTabs227.Tab> order=MultiTabs227.data().tabs;for(int n=0;n<order.size();n++){View other=cells.get(order.get(n).id);if(other==null)continue;if(x>slot+other.getWidth()/2f)target=n;else break;slot+=other.getWidth();}move(target);int[] edge=new int[2];scroll.getLocationOnScreen(edge);int step=PanelUi.dp(v.getContext(),20);if(e.getRawX()<edge[0]+step*2)scroll.scrollBy(-step,0);if(e.getRawX()>edge[0]+scroll.getWidth()-step*2)scroll.scrollBy(step,0);}return true;}if(action==MotionEvent.ACTION_UP){boolean menu=!moved;finish(true);if(menu)host.actions(tab);return true;}return true;}
 void move(int target){ArrayList<SavedTabs227.Tab> tabs=MultiTabs227.data().tabs;int at=tabs.indexOf(tab);if(at<0||target<0||target>=tabs.size()||at==target)return;tabs.remove(at);tabs.add(target,tab);float left=0;for(SavedTabs227.Tab t:tabs){View item=cells.get(t.id);if(item!=null){item.setTranslationX(left-item.getLeft());left+=item.getWidth();}}}
 void finish(boolean save){cells.clear();armed=false;cell.setAlpha(1);if(cell.getParent()!=null)cell.getParent().requestDisallowInterceptTouchEvent(false);if(save)MultiTabs227.save();if(moved){host.preserveStrip=true;host.removeBar();host.bar();}}
}
